-- Table to cache Hebrew explanations and tags generated by Gemini for NASA APOD
create table if not exists public.apod_translations (
  date text primary key,
  original_title text not null,
  original_explanation text not null,
  hebrew_title text not null,
  hebrew_summary text not null,
  tags jsonb not null,
  created_at timestamptz not null default now()
);

-- Row Level Security: ON with no public policies
alter table public.apod_translations enable row level security;
